import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, mix, smoothstep, float, uniform, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, CircleGeometry, CylinderGeometry, Shape,
    ExtrudeGeometry, DirectionalLight, AdditiveBlending,
  } = ctx.THREE;

  const COLORS = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const ACCENT = COLORS.accent || '#ff2a38';
  const PAPER = COLORS.paper || '#e8ecf2';
  const GRAD_TOP = '#191921';
  const GRAD_BOT = '#121218';
  const BORDER = '#26262f';

  const root = new Group();
  root.name = 'feature-triptych';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------------------------------------------------------------
  // Backdrop stage plane (7x6 @ z=-2.5) with spec gradient stops
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(GRAD_TOP), color(GRAD_BOT), uv().y.oneMinus());
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // Node-local rim/accent light (lower-right, opposite the scene key)
  const rim = new DirectionalLight(ACCENT, 0.6);
  rim.position.set(2.5, -1.5, 2.0);
  root.add(rim);

  // Neutral fill from upper-left so lifted cards read a top bevel
  const bevelKey = new DirectionalLight('#e8ecf2', 0.45);
  bevelKey.position.set(-2.0, 2.5, 3.0);
  root.add(bevelKey);

  // ---------------------------------------------------------------
  // Text items (bridge idiom)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const glyphs = items.filter((i) => i.role === 'icon-glyph').map((i) => i.text);
  const titles = items.filter((i) => i.role === 'card-title').map((i) => i.text);
  const bodies = items.filter((i) => i.role === 'body').map((i) => i.text);

  // Text scales chosen so type fits INSIDE a 1.5-unit-wide card and
  // wraps within the interior column instead of spanning the row.
  // title: 20px * 0.006  -> ~0.12 scene-unit em height
  // body:  13px * 0.0065 -> ~0.085 scene-unit em height
  // glyph: 20px * 0.0065 -> ~0.13 scene-unit em height (sits on 0.4 disc)
  const TITLE_SCALE = 0.006;
  const BODY_SCALE = 0.0065;
  const GLYPH_SCALE = 0.0065;
  const INTERIOR_W = 1.26; // 1.5 card - side padding
  const TITLE_MAX_PX = Math.floor(INTERIOR_W / TITLE_SCALE); // ~210
  const BODY_MAX_PX = Math.floor(INTERIOR_W / BODY_SCALE);   // ~193

  // ---------------------------------------------------------------
  // Card construction
  // ---------------------------------------------------------------
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const RADIUS = 0.06;

  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return s;
  }

  const cardShape = roundedRectShape(CARD_W, CARD_H, RADIUS);
  const cardGeo = new ExtrudeGeometry(cardShape, {
    depth: 0.04,
    bevelEnabled: true,
    bevelThickness: 0.01,
    bevelSize: 0.01,
    bevelSegments: 2,
    curveSegments: 12,
  });
  disposables.push(cardGeo);

  const borderShape = roundedRectShape(CARD_W + 0.012, CARD_H + 0.012, RADIUS + 0.006);
  const borderGeo = new ExtrudeGeometry(borderShape, {
    depth: 0.02,
    bevelEnabled: false,
    curveSegments: 12,
  });
  disposables.push(borderGeo);

  const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 48);
  discGeo.rotateX(Math.PI / 2);
  disposables.push(discGeo);

  const shadowGeo = new PlaneGeometry(1.8, 0.5);
  disposables.push(shadowGeo);

  const cardGradient = mix(
    color(GRAD_TOP),
    color(GRAD_BOT),
    positionLocal.y.negate().add(CARD_H / 2).div(CARD_H).clamp(0, 1)
  );

  // Vertical rhythm on the 0.25 baseline grid (card half-height 0.95):
  //   disc center      y = +0.58
  //   title center     y = +0.10   (0.25 gap below disc)
  //   accent tick      y = -0.10
  //   body block ctr   y = -0.46   (0.125+ gap below title, wraps ~3 lines)
  const DISC_Y = 0.58;
  const TITLE_Y = 0.10;
  const TICK_Y = -0.10;
  const BODY_Y = -0.46;

  const cards = [];
  const xs = [-(CARD_W + GAP), 0, CARD_W + GAP];

  for (let i = 0; i < 3; i++) {
    const card = new Group();
    card.name = 'feature-card-' + i;
    card.position.set(xs[i], 0, 0);

    // hairline border frame behind the face
    const borderMat = new MeshStandardNodeMaterial({
      roughness: 0.65,
      metalness: 0.2,
      transparent: true,
    });
    borderMat.colorNode = color(BORDER);
    const border = new Mesh(borderGeo, borderMat);
    border.position.z = -0.015;
    card.add(border);
    disposables.push(borderMat);

    // card face — engineered vertical ramp, PBR within proven ranges
    const faceMat = new MeshPhysicalNodeMaterial({
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      clearcoatRoughness: 0.5,
      transparent: true,
    });
    faceMat.colorNode = cardGradient;
    const face = new Mesh(cardGeo, faceMat);
    card.add(face);
    disposables.push(faceMat);

    // machined icon-seat disc
    const discMat = new MeshPhysicalNodeMaterial({
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      clearcoatRoughness: 0.4,
      transparent: true,
    });
    discMat.colorNode = mix(
      color('#2c2c36'),
      color('#1c1c24'),
      uv().distance(vec2(0.5)).mul(2.0).clamp(0, 1)
    );
    const disc = new Mesh(discGeo, discMat);
    disc.position.set(0, DISC_Y, 0.09);
    card.add(disc);
    disposables.push(discMat);

    // emissive glow core behind the glyph (the frame's brightest element)
    const glowIntensity = uniform(1.6);
    const glowMat = new MeshBasicNodeMaterial({
      transparent: true,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    glowMat.colorNode = color(ACCENT).mul(glowIntensity.mul(0.12));
    glowMat.opacityNode = smoothstep(float(0.5), float(0.05), uv().distance(vec2(0.5)));
    const glowGeo = new CircleGeometry(0.19, 32);
    const glow = new Mesh(glowGeo, glowMat);
    glow.position.set(0, DISC_Y, 0.121);
    card.add(glow);
    disposables.push(glowMat, glowGeo);

    // glyph — accent mono numeral on the disc face
    if (glyphs[i]) {
      const glyph = ctx.fontAtlas.createText(String(glyphs[i]), {
        fontSize: 20,
        color: ACCENT,
        align: 'center',
      });
      glyph.scale.setScalar(GLYPH_SCALE);
      glyph.position.set(0, DISC_Y, 0.125);
      card.add(glyph);
    }

    // title — serif display weight, constrained to the card interior column
    if (titles[i]) {
      const title = ctx.fontAtlas.createText(String(titles[i]), {
        fontSize: 20,
        color: PAPER,
        align: 'center',
        maxWidthPx: TITLE_MAX_PX,
      });
      title.scale.setScalar(TITLE_SCALE);
      title.position.set(0, TITLE_Y, 0.09);
      card.add(title);
    }

    // accent hairline tick between title and body (per-card, tiny accent budget)
    const tickGeo = new PlaneGeometry(0.3, 0.012);
    const tickMat = new MeshBasicNodeMaterial({ transparent: true });
    tickMat.colorNode = color(ACCENT);
    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(0, TICK_Y, 0.09);
    card.add(tick);
    disposables.push(tickGeo, tickMat);

    // body — mono caption tier, wraps inside interior column, high contrast
    if (bodies[i]) {
      const body = ctx.fontAtlas.createText(String(bodies[i]), {
        fontSize: 13,
        color: '#c7cdd8',
        align: 'center',
        maxWidthPx: BODY_MAX_PX,
        letterSpacingPx: 0.2,
      });
      body.scale.setScalar(BODY_SCALE);
      body.position.set(0, BODY_Y, 0.09);
      card.add(body);
    }

    // contact shadow under the card — widens + softens on lift
    const shadowMat = new MeshBasicNodeMaterial({
      transparent: true,
      depthWrite: false,
    });
    shadowMat.colorNode = color('#000000');
    shadowMat.opacityNode = smoothstep(float(0.5), float(0.08), uv().distance(vec2(0.5))).mul(0.5);
    const shadow = new Mesh(shadowGeo, shadowMat);
    shadow.position.set(0, -1.06, -0.1);
    card.add(shadow);
    disposables.push(shadowMat);

    root.add(card);
    cards.push({ card, shadow, glowIntensity, hoverTl: null });
  }

  // foreground accent rule — third depth plane, <10% frame accent budget
  const ruleGeo = new PlaneGeometry(0.5, 0.02);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = color(ACCENT);
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(0, -1.42, 0.4);
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ---------------------------------------------------------------
  // Mount: stagger-cards / fade-up, weighted ease (no linear)
  // ---------------------------------------------------------------
  const cardMats = cards.map(({ card }) => {
    const mats = [];
    card.traverse((o) => {
      if (o.material) {
        o.material.transparent = true;
        mats.push(o.material);
      }
    });
    return mats;
  });

  const mountTl = gsap.timeline();
  cards.forEach(({ card }, i) => {
    const mats = cardMats[i];
    mats.forEach((m) => { m.opacity = 0; });
    card.position.y = -0.2;
    const state = { t: 0 };
    mountTl.to(state, {
      t: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => {
        card.position.y = -0.2 * (1 - state.t);
        for (const m of mats) m.opacity = state.t;
      },
    }, i * 0.08);
  });
  // weighted settle on the row
  mountTl.fromTo(root.scale, { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.55);
  timelines.push(mountTl);

  // ---------------------------------------------------------------
  // Hover lift
  // ---------------------------------------------------------------
  function liftCard(i, lifted) {
    const entry = cards[i];
    if (!entry) return;
    if (entry.hoverTl) entry.hoverTl.kill();
    const tl = gsap.timeline();
    tl.to(entry.card.position, {
      y: lifted ? 0.06 : 0,
      z: lifted ? 0.12 : 0,
      duration: 0.18,
      ease: 'power2.out',
    }, 0);
    tl.to(entry.shadow.scale, {
      x: lifted ? 1.18 : 1,
      y: lifted ? 1.12 : 1,
      duration: 0.18,
      ease: 'power2.out',
    }, 0);
    tl.to(entry.shadow.position, {
      y: lifted ? -1.1 : -1.06,
      duration: 0.18,
      ease: 'power2.out',
    }, 0);
    tl.to(entry.glowIntensity, {
      value: lifted ? 2.2 : 1.6,
      duration: 0.18,
      ease: 'power2.out',
    }, 0);
    entry.hoverTl = tl;
    timelines.push(tl);
  }

  function findCardIndex(obj) {
    let o = obj;
    while (o) {
      const idx = cards.findIndex((c) => c.card === o);
      if (idx !== -1) return idx;
      o = o.parent;
    }
    return -1;
  }

  root.userData.handlers = {
    pointerenter: (e) => {
      const idx = e && e.object ? findCardIndex(e.object) : -1;
      if (idx !== -1) liftCard(idx, true);
    },
    pointerleave: () => {
      for (let i = 0; i < cards.length; i++) liftCard(i, false);
    },
    pointermove: (e) => {
      const idx = e && e.object ? findCardIndex(e.object) : -1;
      for (let i = 0; i < cards.length; i++) liftCard(i, i === idx);
    },
  };

  cards.forEach((entry, i) => {
    entry.card.userData.handlers = {
      pointerenter: () => liftCard(i, true),
      pointerleave: () => liftCard(i, false),
    };
  });

  // ---------------------------------------------------------------
  // Cinematic primitives from config (none shipped, applied if present)
  // ---------------------------------------------------------------
  for (const primitive of (config.cinematicPrimitives || [])) {
    if (ctx.primitives[primitive.name]) {
      primHandles.push(ctx.primitives[primitive.name](root, primitive.params));
    }
  }

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const entry of cards) {
      if (entry.hoverTl) entry.hoverTl.kill();
    }
    for (const h of primHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    root.traverse((o) => {
      if (o.geometry && typeof o.geometry.dispose === 'function') o.geometry.dispose();
      if (o.material && typeof o.material.dispose === 'function') o.material.dispose();
    });
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
